# Synthara Installer
Write-Host '=== Synthara Installer ===' -ForegroundColor Cyan

try {
    python --version 2>&1 | Out-Null
} catch {
    Write-Host 'Python not found! Install from https://python.org' -ForegroundColor Red
    exit 1
}
try {
    node --version 2>&1 | Out-Null
} catch {
    Write-Host 'Node.js not found! Install from https://nodejs.org' -ForegroundColor Red
    exit 1
}

Write-Host '[*] Installing backend...' -ForegroundColor Green
New-Item -ItemType Directory -Path backend -Force | Out-Null
$b64b = ''
$b = [Convert]::FromBase64String($b64b)
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'backend\archive.zip'), $b)
Expand-Archive -Path backend\archive.zip -DestinationPath backend -Force
Remove-Item backend\archive.zip -Force
pip install -r backend\requirements.txt 2>&1 | Out-Null

Write-Host '[*] Installing frontend...' -ForegroundColor Green
New-Item -ItemType Directory -Path frontend -Force | Out-Null
$b64f = ''
$f = [Convert]::FromBase64String($b64f)
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'frontend\archive.zip'), $f)
Expand-Archive -Path frontend\archive.zip -DestinationPath frontend -Force
Remove-Item frontend\archive.zip -Force
Set-Location frontend
npm install 2>&1 | Out-Null
npm run build 2>&1 | Out-Null
Set-Location ..

Write-Host '[*] Generating wallet...' -ForegroundColor Green
python -c "import json; from solders.keypair import Keypair; kp = Keypair(); wallet = {'public_key': str(kp.pubkey()), 'private_key_hex': bytes(kp.secret()).hex()}; json.dump(wallet, open('synthara_wallet.json', 'w'), indent=2); print(wallet['public_key'])" 2>&1 | Out-Null

Write-Host ''
Write-Host '=== Installation Complete ===' -ForegroundColor Cyan
Write-Host 'Run: python backend\app.py' -ForegroundColor Yellow
Write-Host 'Then open http://localhost:8000' -ForegroundColor White
Write-Host 'Admin: /admin with key sk-admin-synthara-root' -ForegroundColor Cyan
